 soundFX(type){if(type==='flight'){noiseWhoosh(.8,.08);soundNote(90,.8,'sine',.08,0,42);soundNote(230,.23,'sine',.015,.55,500)}if(type==='boarding'){noiseWhoosh(1.3,.12);soundNote(55,1.7,'sine',.07,0,110);soundNote(780,.2,'sine',.04,1.15);soundNote(1170,.2,'sine',.025,1.4)}if(type==='radar'){soundNote(1050,.22,'sine',.045,0,720,-.2);soundNote(2100,.13,'sine',.012,.06,1500,.2)}if(type==='collect'){noiseWhoosh(.35,.035);soundNote(470,.15,'triangle',.03);soundNote(940,.21,'sine',.03,.14)}if(type==='click'){soundNote(720,.085,'sine',.025,0,480)}if(type==='success'){[523.25,659.25,783.99,1046.5].forEach((f,i)=>{soundNote(f,.48,'sine',.045,i*.115);soundNote(f*2,.26,'sine',.007,i*.115)})}}\nfunction chime(){soundFX('success')}\nfunction syncHum(){if(!audio)return;if(audioHum){audioHum.gain.cancelScheduledValues(audio.currentTime);audioHum.gain.setTargetAtTime(state.sound&&state.started?.006:0,audio.currentTime,.3);return}if(!state.sound||!state.started)return;const a=ensureAudio();if(!a)return;audioHum=a.createGain();audioHum.gain.value=.006;audioHum.connect(audioMaster);for(const f of [49,98.3]){const o=a.createOscillator();o.type='sine';o.frequency.value=f;o.connect(audioHum);o.start()}}\nfunction syncSoundUi(){$('soundBtn').innerHTML=svg(state.sound?'sound':'mute');$('soundBtn').setAttribute('aria-label',state.sound?'Sesi kapat':'Sesi aç');$('soundBtn').title=state.sound?'Sesi kapat':'Sesi aç'}\nfunction toggleSound(){state.sound=!state.sound;$('soundBtn').innerHTML=svg(state.sound?'sound':'mute');$('soundBtn').setAttribute('aria-label',state.sound?'Sesi kapat':'Sesi aç');$('soundBtn').title=state.sound?'Sesi kapat':'Sesi aç';if(state.sound){ensureAudio();soundFX('click')}else if('speechSynthesis'in window)speechSynthesis.cancel();syncHum();persist()}\nfunction start(){if(state.started)return;state.started=true;document.body.classList.remove('no-start');document.body.classList.add('boarding-mode');$('intro').hidden=true;boardingAt=performance.now();$('boarding').hidden=