3.);vec3 c=mix(vec3(.98,.23,.025),vec3(1.,.83,.32),s*.4+.65);gl_FragColor=vec4(c,1.);}'}));const g=new THREE.Group();g.add(sunMesh);g.add(atmosphere(3.14,'#ffbf55'));g.visible=false;planetGroups.sun=g;planets.sun=sunMesh;scene.add(g)}\nfunction buildMoonSystem(id,texture){const arr=MOONS[id];if(!arr)return;moonsByPlanet[id]=[];arr.forEach((m,i)=>{const geo=m.rough?new THREE.IcosahedronGeometry(m.size,1):new THREE.SphereGeometry(m.size,24,16);const mat=new THREE.MeshStandardMaterial({map:texture,color:m.color,roughness:1,emissive:m.color,emissiveIntensity:.09});const mesh=new THREE.Mesh(geo,mat);if(m.rough)mesh.scale.set(1.35,.8,.9);const carrier=new THREE.Group();carrier.userData={moon:m,phase:(i-(arr.length-1)/2)*1.1+.4,radius:(id==='saturn'?6.3:bodyData(id).radius+1.1)+i*.4,index:i};carrier.add(mesh);planetGroups[id].add(carrier);moonsByPlanet[id].push(carrier)})}\nfunction buildSolarSystem(){solarRoot=new THREE.Group();solarRoot.visible=false;const center=new THREE.Mesh(new THREE.SphereGeometry(1.2,40,28),sunMesh.material);solarRoot.add(center);const sunlight=new THREE.PointLight(0xffdbad,14,65,1);solarRoot.add(sunlight);solarRoot.add(atmosphere(1.29,'#ffc574'));solarBodies=[{id:'sun',mesh:center,orbit:0}];const radii=[3.2,4.8,6.6,8.7,11.5,14.7,18,21.5],phases=[.3,2.3,4.0,5.1,1.2,3.1,4.5,5.7];DATA.forEach((d,i)=>{const pts=[];for(let j=0;j<=160;j++){const a=j/160*Math.PI*2;pts.push(new THREE.Vector3(Math.cos(a)*radii[i],0,Math.sin(a)*radii[i]))}const line=new THREE.Line(new THREE.BufferGeometry().setFromPoints(pts),new THREE.LineBasicMaterial({color:0x5b8990,transparent:true,opacity:.25}));solarRoot.add(line);const group=new THREE.Group(),mesh=new THREE.Mesh(new THREE.SphereGeometry(i<4?.22+i*.035:i===4?.70:i===5?.55:.4,24,18),planets[d.id].material);group.add(mesh);if(d.id==='saturn'){const ring=new THREE.Mesh(new THREE.RingGeometry(.79,1.13,64),new THREE.MeshBasicMaterial({map:ringTexture(),transparent:true,side:THREE.DoubleSide,opacity:.9,depthWrite:false}));ring.rotation.x=1.1;group.add(ring)}solarRoot.add(group);solarBodies.push({id:d.id,mesh:group,orbit:radii[i],phase:phases[i],speed:.007+(8-i)*.0015})});const random=randSeed(38),points=[];for(let i=0;i<420;i++){const a=random()*Math.PI*2,r=9.5+random()*.65;points.push(Math.cos(a)*r,(random()-.5)*.25,Math.sin(a)*r)}const belt=new THREE.BufferGeometry();belt.setAttribute('position',new THREE.Float32BufferAttribute(points,3));solarRoot.add(new THREE.Points(belt,new THREE.PointsMaterial({color:0x9bb4bb,size:.055,transparent:true,opacity:.33})));scene.add(solarRoot)}\nfunction updateMoonButtons(){$('moonLayer').innerHTML='';const arr=moonsByPlanet[state.selected]||[];arr.forEach((node,i)=>{const b=document.createElement('button');b.className='moon-hit';b.dataset.moon=i;b.textContent=node.userData.moon.name;b.setAttribute('aria-label',node.userData.moon.name+' uydusu hakkında bilgi');b.onclick=()=>showMoonInfo(state.selected,i);$('moonLayer').appendChild(b)})}\nfunction updateAtlasButtons(){$('atlasLayer').innerHTML='';if(state.selected!=='system')return;for(const d of solarBodies){const b=document.createElement('button');b.className='atlas-hit';b.dataset.body=d.id;b.style.setProperty('--dot',bodyData(d.id).color);b.textContent=bodyData(d.id).name;b.setAttribute('aria-label',bodyData(d.id).name+' hakkında bilgi ve keşif');b.onclick=()=>showBodyInfo(d.id,true);$('atlasLayer').appendChild(b)}}\nfunction projectedElement(el,node,hideOccluded=false){if(!el)return;const w=new THREE.Vector3();node.getWorldPosition(w);const distance=camera.position.distanceTo(w),ndc=w.clone().project(camera);let show=ndc.z>=-1&&ndc.z<=1&&Math.abs(ndc.x)<.97&&Math.abs(ndc.y)<.89;if(hideOccluded&&show){const ray=new THREE.Ray(camera.position,w.clone().sub(camera.position).normalize()),center=new THREE.Vector3();planets[state.selected].getWorldPosition(center);const hit=ray.intersectSphere(new THREE.Sphere(center,bodyData(state.selected).radius),new THREE.Vector3());if(hit&&camera.position.distanceTo(hit)<distance-.2)show=false}el.style.visibility=show?'visible':'hidden';el.style.left=((ndc.x*.5+.5)*innerWidth)+'px';el.style.top=((-ndc.y*.5+.5)*innerHeight)+'px'}\nfunction updateUniverse(dt,now){if(sunMesh)sunMesh.material.uniforms.time.value=elapsed;for(const [id,nodes]of Object.entries(moonsByPlanet)){nodes.forEach((node,i)=>{const a=node.userData.phase+(reduced?0:elapsed*(.035+i*.004));node.position.set(Math.sin(a)*node.userData.radius,.45+Math.sin(a*.7)*.3,Math.cos(a)*node.userData.radius);node.children[0].rotation.y=reduced?0:elapsed*.05})}solarBodies.forEach(b=>{if(b.orbit){const a=b.phase+(reduced?0:elapsed*b.speed);b.mesh.position.set(Math.cos(a)*b.orbit,0,Math.sin(a)*b.orbit);b.mesh.rotation.y=reduced?0:elapsed*.1}});if(planetTransition){const t=clamp((now-planetTransition.start)/planetTransition.duration,0,1),p=smooth(t),from=rootFor(planetTransition.from),to=rootFor(planetTransition.to);from.position.set(-15*p,0,-4*p);from.scale.setScalar(1-p*.1);to.position.set(15*(1-p),0,-4*(1-p));to.scale.setScalar(.9+p*.1);if(t>=1){from.visible=false;normalizeRoot(from);normalizeRoot(to);planetTransition=null;$('flightStatus').classList.remove('active')}}\nconst canShow=state.started&&!boardingAt&&!planetTransition&&$('modalOverlay').hidden&&state.activeLab!=='size';const moons=moonsByPlanet[state.selected]||[];for(let i=0;i<moons.length;i++){const b=$('moonLayer').children[i];if(!b)continue;if(!canShow)b.style.visibility='hidden';else projectedElement(b,moons[i],true)}for(let i=0;i<solarBodies.length;i++){const b=$('atlasLayer').children[i];if(!b)continue;if(!canShow||state.selected!=='system')b.style.visibility='hidden';else projectedElement(b,solarBodies[i].mesh)}if(state.scanning&&now>=radarNextPing){soundFX('radar');radarNextPing=now+600}}\nfunction showBodyInfo(id,fromSystem=false){const d=bodyData(id);showModal(modalHead(d.name,id==='sun'?'YILDIZ DOSYASI':id==='system'?'GÜNEŞ SİSTEMİ':'GEZEGEN DOSYASI')+'<p>'+d.fact+'</p><div class="about-grid"><div class